// The dungeon on the GameCube: floors generated by the port (game::Session, the same code
// the PC checks against the real game), shown a room at a time.
//
// The game's controls (ReadPad): the stick walks Will (the game's HeroMerchantController and
// Animator; push into a door to go through it), the D-pad too; A attack, R roll, X secondary,
// B pendant, Y inventory, L potion, Z swap weapons, START pause, C-stick map (what's ported so
// far acts on them). Debug, holding START:
//   + A      down to the next floor (after the third, the dungeon starts over)
//   + L / R  the dungeon before / after (Golem, Forest, Desert, Tech)
//   + Y      a new run (a new seed)
//   + Z      full widescreen (anamorphic, for a 16:9 TV) / letterboxed (for a 4:3 one)
#pragma once

#include <map>
#include <memory>
#include <string>
#include <vector>

#include <gccore.h>

#include "DiscData.h"
#include "RoomEnemies.h"
#include "game/Composite.h"
#include "game/HeroMerchantController.h"
#include "game/Session.h"
#include "game/Weapon.h"
#include "unity/Animator.h"
#include "unity/Physics2D.h"
#include "render/RoomDraw.h"
#include "render/SpriteBank.h"

class MoonGame {
public:
    MoonGame();
    ~MoonGame();

    bool Initialize();
    void Update(float deltaTime);
    // Draws the current room into the framebuffer, letterboxed or anamorphic (GX state is the
    // caller's to restore).
    void Render(float width, float height);
    const std::string& Status() const { return status_; }

private:
    struct GxTexture {
        GXTexObj obj;
        GXTlutObj tlut;
        bool paletted = false;
        void* texels = nullptr;
    };

    void NewFloor();
    // `from`: the side Will comes in by (0 north, 1 south, 2 west, 3 east), -1 the middle;
    // `arrival`: where (the door he left by: its arrival point, in front of this room's door).
    void EnterRoom(int cell, int from = -1, const unity::Vector2* arrival = nullptr);
    void SetUpHero();
    void ReadPad();
    void UpdateHero(float deltaTime);
    bool HeroQuad(render::DrawQuad& q) const;
    bool WeaponQuad(const render::DrawQuad& hero, render::DrawQuad& q) const;
    void FreeRoomTextures();
    void FreeSpriteTextures();
    const GxTexture* SpriteTexture(const render::Sprite& sprite);
    // `flash` > 0: the sprite shader's _FlashAmount, towards `flashColor` (the damaged effect).
    void DrawQuad(const render::DrawQuad& q, const GxTexture& tex, float flash = 0.0f, GXColor flashColor = GXColor{255, 255, 255, 255});
    // An untextured rectangle in world units (the HUD).
    void DrawRect(float x0, float y0, float x1, float y1, GXColor color);
    // Will's health, top left of the view: a stand-in for the game's HUD (its art isn't
    // extracted yet): the bar in the health bar's red, a pip per shield.
    void DrawHud(unity::Vector2 viewCenter);

    DiscData data_;
    game::Session session_{data_};
    std::unique_ptr<game::Floor> floor_;
    render::SpriteBank bank_;
    std::map<game::Culture, game::TileTextures> tiles_;
    game::TileTextures commonTiles_;
    int culture_ = 1; // 1..4
    int level_ = 0;   // 0..2
    int seed_ = 1;
    int cell_ = 0;
    bool widescreen_ = true;
    render::RoomDraw room_;
    std::map<const render::Sprite*, GxTexture> spriteTextures_;     // this floor's, as drawn
    std::map<const game::RoomTexture*, GxTexture> roomTextures_;    // this room's painted ones
    std::string status_;

    unity::AnimatorController heroAnimator_;
    unity::Physics2D physics_; // the room's colliders
    std::unique_ptr<game::HeroMerchantController> hero_;
    float heroDepthOffset_ = 0.0f; // his SpriteDepthOrderRender's offset
    float abilityCooldown_ = 0.0f; // the starting ability's (items.json)
    // The starting weapon (items.json's first in initialEquippedItems with a weaponType: the
    // Broom Spear): its item, controller and the Weapon he carries.
    std::string weaponItem_, weaponArt_, weaponType_;
    unity::AnimatorController weaponAnimator_;
    std::unique_ptr<game::Weapon> weapon_;
    // The room's enemies (the ported ones), what they're made from, and Will's hits on them.
    unity::AnimatorController babySlimeAnimator_;
    json::Value enemyStats_;
    unity::Physics2DSettings physicsSettings_;
    RoomEnemies::Attack attack_;
    float weaponStrength_ = 0.0f;
    std::unique_ptr<RoomEnemies> enemies_;
    int defaultLayer_ = 0;

    // This frame's pad, as the game's actions (ReadPad).
    struct Pad {
        unity::Vector2 stick;
        bool action1 = false, action2Held = false, action3 = false, action3Held = false, action4 = false;
        bool leftTrigger = false, rightTrigger = false, bumper = false, select = false, start = false;
        bool debug = false; // START held
    } pad_;
    bool startCombo_ = false, cstickHeld_ = false;
    uint16_t padHeld_ = 0, padPressed_ = 0; // pad 1's buttons, and this frame's new presses
};
